"""Regenerate the current contract matrix and native-v1 fixture outputs.

Does not modify the immutable TypeScript reference or historical fixtures.
Run with the repository's Python environment from any working directory.
"""
from pathlib import Path
import shutil
import tempfile

from prosaic import apply
from prosaic.registry import builtin_registry, registry_for_config, REGISTRY_VERSION, slot_for

ROOT = Path(__file__).resolve().parents[1]


def contract_matrix():
    descriptors = builtin_registry()
    lines = ['# Prosaic Target Contract Matrix', '',
        '> Generated by `scripts/generate_contracts.py`. Baseline descriptors retain the frozen v0.2.0 behavior; fresh projects use the native-v1 overlay below.', '',
        f'**Baseline registry version:** {REGISTRY_VERSION["version"]} · **Ruler-parity ref:** ruler@0.4.0 · **Parity baseline:** 35 · **Targets:** {len(descriptors)}', '',
        '| id | label | destination dir | format | ext | arg token | capabilities |',
        '| --- | --- | --- | --- | --- | --- | --- |']
    for desc in descriptors:
        caps = '+'.join(k for k, enabled in desc['capabilities'].items() if enabled)
        lines.append(f'| {desc["id"]} | {desc["label"]} | `{desc["destinationDir"]}` | {desc["format"]} | `{desc["extension"]}` | `{desc["argumentToken"]}` | {caps} |')
    native = registry_for_config({'outputContracts': 'native-v1'})
    lines += ['', '## Native-v1 overlay (fresh-project default)', '',
        f'**Registry version:** {native.version()["version"]}. Fresh projects select this overlay automatically; existing projects can enable it with `outputContracts: native-v1`. All other target contracts remain unchanged.', '',
        '| target | artifact | output | ownership |', '| --- | --- | --- | --- |']
    for target in ('claude-code', 'agents-md'):
        desc = native.get(target)
        for kind in ('rule', 'skill', 'subagent', 'command'):
            if not desc['capabilities'][kind]:
                continue
            if kind == 'rule' and desc.get('aggregate'):
                path, ownership = desc['aggregate']['file'], 'managed block; local content preserved'
            else:
                slot = slot_for(desc, {'subagent': 'agent'}.get(kind, kind))
                path = slot['dir'] + '/<name>'
                path += '/' + slot['primaryName'] if slot.get('layout') == 'bundle' else slot.get('extension', desc['extension'])
                ownership = 'whole file; hash-checked mutation'
            lines.append(f'| {target} | {kind} | `{path}` | {ownership} |')
    return '\n'.join(lines) + '\n'


def generate():
    (ROOT / 'docs/contract-matrix.md').write_text(contract_matrix())
    fixture = ROOT / 'conformance-fixtures/native-v1'
    with tempfile.TemporaryDirectory(prefix='prosaic-contracts-') as tmp:
        project = Path(tmp)
        shutil.copytree(fixture / 'source', project / '.prosaic')
        (project / 'prosaic.config.yaml').write_text('outputContracts: native-v1\ntargets: [claude-code, agents-md]\n')
        report = apply(project)
        expected = fixture / 'expected'
        # Delete only previously generated fixture output, never source fixtures.
        if expected.exists():
            shutil.rmtree(expected)
        for operation in report['plan']['writes']:
            dest = expected / operation['path']
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_bytes((project / operation['path']).read_bytes())


if __name__ == '__main__':
    generate()
